let demoRecords=null;
let demoCompany='existing',demoYear=new Date().getMonth()<3?new Date().getFullYear()-1:new Date().getFullYear(),demoUser={id:1,name:'DEMO ADMIN',role:'admin'};
let state={masters:[],purchases:[],sales:[],expenses:[],expense_items:[],documents:[],users:[],audit:[]},user=null,csrf='',page='dashboard',masterKind='vehicle',filter='all',search='',chartMode='6m';
const kinds={vehicle:'Vehicles',bank:'Banks',client:'Clients & sellers',party:'Parties',document:'Document types',yard:'Yards',portal:'Portals'};
const kindSingular={vehicle:'vehicle',bank:'bank',client:'client / seller',party:'party',document:'document type',yard:'yard',portal:'portal'};
const nav=[['dashboard','grid','Overview'],['vehicles','car','Vehicle inventory'],['purchases','buy','Purchases'],['sales','sell','Sales'],['expenses','receipt','Expenses'],['documents','folder','Documents'],['reports','chart','Profit reports'],['masters','layers','Masters'],['users','users','Users & access'],['activity','clock','Activity log']];
function can(action){return user&&({purchase:['admin','manager'],sale:['admin','manager'],expense:['admin','manager','accountant'],master:['admin','manager','accountant'],document:['admin','manager','accountant'],user:['admin']}[action]||[]).includes(user.role)}
function m(id){return state.masters.find(x=>+x.id===+id)||{name:'—',details:'',contact:'',address:'',city:''}}
function all(kind){return state.masters.filter(x=>x.kind===kind)}
function expTotal(id){return state.expense_items.filter(x=>state.expenses.some(e=>+e.id===+x.expense_id&&+e.vehicle_id===+id)).reduce((a,x)=>a+Number(x.total),0)}
function ledger(){return state.purchases.map(p=>{const s=state.sales.find(x=>+x.vehicle_id===+p.vehicle_id),v=m(p.vehicle_id),expenses=expTotal(p.vehicle_id),cost=+p.amount+(+p.yard_expense)+expenses;return {...p,vehicle:v,sale:s,expenses,cost,profit:s?+s.amount-(+s.sale_expense)-cost:null,status:s?'Sold':'In stock'}})}
function brand(){return `<div class="brand"><span class="brandmark">${icon('car')}</span><div>The Car Project<small>DEALERSHIP MANAGEMENT</small></div></div>`}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function seed(){const masters=[{id:1,kind:'vehicle',name:'PB10EX4582',details:'Maruti Suzuki Baleno · 2022 · Petrol'},{id:2,kind:'vehicle',name:'PB10HT9021',details:'Hyundai Creta · 2021 · Diesel'},{id:3,kind:'vehicle',name:'CH01CC7712',details:'Honda City · 2020 · Petrol'},{id:4,kind:'vehicle',name:'PB08FA3310',details:'Tata Nexon · 2023 · Petrol'},{id:5,kind:'vehicle',name:'PB10GR6605',details:'Mahindra XUV300 · 2021 · Diesel'},{id:6,kind:'vehicle',name:'HR26DK1840',details:'Maruti Suzuki Swift · 2022 · Petrol'},
{id:10,kind:'bank',name:'HDFC Bank',details:'Vehicle finance branch',city:'Ludhiana'},{id:11,kind:'bank',name:'ICICI Bank',city:'Chandigarh'},
{id:20,kind:'client',name:'Aarav Motors',contact:'9876500101',city:'Ludhiana',details:'Seller / dealership'},{id:21,kind:'client',name:'Rohan Sharma',contact:'9876500102',city:'Ludhiana',details:'Buyer'},{id:22,kind:'client',name:'Simran Kaur',contact:'9876500103',city:'Chandigarh',details:'Buyer'},
{id:30,kind:'party',name:'Precision Auto Care',contact:'9876500111',city:'Ludhiana'},{id:31,kind:'party',name:'City Detailing Studio',contact:'9876500112',city:'Ludhiana'},
{id:40,kind:'yard',name:'Ludhiana Auto Yard',address:'Ferozepur Road',city:'Ludhiana'},{id:41,kind:'portal',name:'Cars24'}];
['RC','Insurance','NOC','RTO Kit','Release Letter From Bank','Permit','Other'].forEach((name,i)=>masters.push({id:50+i,kind:'document',name}));
const purchases=[['2026-06-12',430000,2500],['2026-07-05',780000,4000],['2026-08-18',510000,3000],['2026-09-10',690000,3500],['2026-10-12',615000,2500],['2026-11-02',425000,2000]].map((x,i)=>({id:i+1,vehicle_id:i+1,bank_id:i%2?11:10,client_id:20,yard_id:40,portal_id:41,purchase_date:x[0],amount:x[1],yard_expense:x[2],manager_name:'Vikram Singh',manager_contact:'9876500120'}));
const sales=[{id:1,vehicle_id:1,client_id:21,sale_date:'2026-07-20',amount:495000,sale_expense:2500,salesperson:'Vikram Singh'},{id:2,vehicle_id:3,client_id:22,sale_date:'2026-09-16',amount:580000,sale_expense:3000,salesperson:'Vikram Singh'},{id:3,vehicle_id:5,client_id:21,sale_date:'2026-11-05',amount:695000,sale_expense:2500,salesperson:'Vikram Singh'}];
const expenses=purchases.map((p,i)=>({id:i+1,vehicle_id:p.vehicle_id,party_id:i%2?31:30,bill_no:'DEMO-'+(101+i),expense_date:p.purchase_date}));
const expense_items=expenses.map((e,i)=>({id:i+1,expense_id:e.id,name:i%2?'Interior detailing':'Service & repairs',qty:1,total:[12000,22000,14500,18000,16000,6500][i]}));
return {masters,purchases,sales,expenses,expense_items,documents:[],users:[{id:1,name:'Mohit Singla',username:'mohit',role:'admin',active:1}],audit:[{id:1,user_name:'Mohit Singla',action:'Recorded sale',entity_id:3,created_at:'2026-11-05 12:35:00'},{id:2,user_name:'Mohit Singla',action:'Recorded purchase',entity_id:6,created_at:'2026-11-02 10:10:00'}]}}

const uppercaseFields=new Set(['name','contact','manager_name','manager_contact','salesperson','address','city','details','bill_no']);
function normalizeEntry(action,data){
 if(!['master','purchase','sale','expense','user'].includes(action)||!data||data instanceof FormData)return data;
 const normalized={...data};
 for(const key of uppercaseFields)if(typeof normalized[key]==='string')normalized[key]=normalized[key].trim().toUpperCase();
 if(Array.isArray(data.items))normalized.items=data.items.map(item=>({...item,name:String(item.name??'').trim().toUpperCase()}));
 if(Array.isArray(data.bills))normalized.bills=data.bills.map(bill=>({...bill,bill_no:String(bill.bill_no??'').trim().toUpperCase(),name:String(bill.name??'').trim().toUpperCase()}));
 return normalized;
}
function normalizeInput(input){
 if(!(input instanceof HTMLInputElement)||input.type==='password'||!input.closest('#entry-form,#master-form'))return;
 if(!uppercaseFields.has(input.name)&&!input.hasAttribute('data-name')&&!input.hasAttribute('data-bill-no'))return;
 const start=input.selectionStart,end=input.selectionEnd;
 input.value=input.value.toUpperCase();
 if(start!==null&&end!==null)input.setSelectionRange(start,end);
}
if(typeof document!=='undefined'){
 document.addEventListener('input',event=>{if(!event.isComposing)normalizeInput(event.target)});
 document.addEventListener('compositionend',event=>normalizeInput(event.target));
}


function applySession(result){user=result.user;csrf=result.csrf;workspaceToken=result.workspace_token||'';workspace=result.workspace||null;companies=result.companies||companies;}
function inYear(date){return !workspace||(date>=workspace.financial_year.start&&date<=workspace.financial_year.end);}
function yearPurchases(){return state.purchases.filter(p=>inYear(p.purchase_date));}
function yearSales(){return state.sales.filter(s=>inYear(s.sale_date));}
function yearExpenses(){return state.expenses.filter(e=>inYear(e.expense_date));}
function viewLedger(){return ledger().filter(p=>!p.sale||inYear(p.sale.sale_date)||inYear(p.purchase_date)||yearExpenses().some(e=>+e.vehicle_id===+p.vehicle_id));}
function entryToday(){if(!workspace)return today();return today()<workspace.financial_year.start?workspace.financial_year.start:today()>workspace.financial_year.end?workspace.financial_year.end:today();}
function demoStorageKey(){return 'tcp-preview-v2-company-'+demoCompany;}

function demoSeed(company){
 const data=seed();const now=new Date(),fy=now.getFullYear()-(now.getMonth()<3?1:0);data.purchases[0].purchase_date=(fy-1)+'-12-15';if(company==='existing')return data;
 const prefix=company==='second_company'?'DL01':'HR26',factor=company==='second_company'?1.2:0.8;
 data.masters=data.masters.map(m=>({...m,name:m.kind==='vehicle'?prefix+m.name.slice(4):m.kind==='client'?(company==='second_company'?'DELHI ':'GURUGRAM ')+m.name:m.name}));
 data.purchases=data.purchases.map(p=>({...p,amount:Math.round(Number(p.amount)*factor)}));
 data.sales=data.sales.map(s=>({...s,amount:Math.round(Number(s.amount)*factor)}));
 data.expenses=data.expenses.map(e=>({...e,bill_no:(company==='second_company'?'TWO-':'THREE-')+e.bill_no}));
 data.audit=[];return data;
}

function emptyCompanyState(){const s=seed();for(const k of ['purchases','sales','expenses','expense_items','documents','audit'])s[k]=[];s.masters=s.masters.filter(m=>['document','portal'].includes(m.kind));return s;}
function demoSession(){const name=demoCompany==='existing'?'DEMO COMPANY ONE':demoCompany==='second_company'?'DEMO COMPANY TWO':'DEMO COMPANY THREE',range=y=>({year:y,label:y+'–'+(y+1),start:y+'-04-01',end:(y+1)+'-03-31'});return {user:demoUser,csrf:'preview',workspace_token:demoCompany+'-'+demoYear,workspace:{company_key:demoCompany,company_name:name,financial_year:range(demoYear)},companies:['existing','second_company','third_company'].map(key=>({key,name:key==='existing'?'DEMO COMPANY ONE':key==='second_company'?'DEMO COMPANY TWO':'DEMO COMPANY THREE',years:Array.from({length:9},(_,i)=>range(new Date().getFullYear()+1-i))}))};}
function workspaceFields(){return `<div class="field"><label for="workspace-company">Company</label><select id="workspace-company" name="company_key">${companies.map(c=>`<option value="${esc(c.key)}" ${c.key===workspace?.company_key?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label for="workspace-year">Financial year · April–March</label><select id="workspace-year" name="financial_year"></select></div>`;}
function bindWorkspaceFields(root){
 const company=$('#workspace-company',root),year=$('#workspace-year',root);
 function updateYears(){const c=companies.find(c=>c.key===company.value);year.innerHTML=(c?.years||[]).map(y=>`<option value="${y.year}" ${y.year===workspace?.financial_year.year?'selected':''}>${y.label}</option>`).join('');}
 company.onchange=updateYears;updateYears();
}
async function chooseWorkspace(companyKey,year){
 const result=await request('select_workspace',{company_key:companyKey,financial_year:Number(year)});applySession(result);
 page='dashboard';search='';filter='all';state={masters:[],purchases:[],sales:[],expenses:[],expense_items:[],documents:[],users:[],audit:[]};
 if(DEMO){try{state=JSON.parse(localStorage.getItem(demoStorageKey()))||demoSeed(demoCompany)}catch{state=demoSeed(demoCompany)}}
 if(DEMO)demoRecords=state;
 if(user){await refresh();render()}else loginView();
}
function openWorkspace(){
 const {layer,close}=modal('Select company & financial year','Switching companies signs you out. Years share that company’s vehicle history.',`<form><div class="formgrid">${workspaceFields()}</div><div class="error" role="alert"></div><div class="formfooter"><small>Unsaved entry forms must be closed first.</small><button type="submit" class="btn primary">Open workspace</button></div></form>`);
 const form=$('form',layer);bindWorkspaceFields(form);form.onsubmit=async e=>{e.preventDefault();const btn=$('[type=submit]',form);btn.disabled=true;try{const data=Object.fromEntries(new FormData(form));await chooseWorkspace(data.company_key,data.financial_year);close()}catch(err){$('.error',form).textContent=err.message}finally{btn.disabled=false}};
}

async function request(action,data){data=normalizeEntry(action,data);if(DEMO)return demoRequest(action,data);const isForm=data instanceof FormData;const r=await fetch('api.php?action='+action,{method:data?'POST':'GET',credentials:'same-origin',headers:{'X-Workspace-Token':workspaceToken,...(data?{'X-CSRF-Token':csrf,...(!isForm?{'Content-Type':'application/json'}:{})}:{})},body:data?(isForm?data:JSON.stringify(data)):undefined});let result;try{result=await r.json()}catch{throw Error('Server is not configured. Check PHP and database setup.')}if(!r.ok)throw Error(result.error||'Request failed');return result}
function persist(){try{localStorage.setItem(demoStorageKey(),JSON.stringify(demoRecords||state))}catch{toast('Browser storage is full. Reset preview data to continue.')}}
function demoRequest(action,d){
 if(action==='state'){const records=demoRecords||state;const end=workspace?.financial_year.end||'2101-03-31';const result={...records,purchases:records.purchases.filter(p=>p.purchase_date<=end),sales:records.sales.filter(p=>p.sale_date<=end),expenses:records.expenses.filter(p=>p.expense_date<=end)};result.expense_items=records.expense_items.filter(i=>result.expenses.some(e=>+e.id===+i.expense_id));result.audit=records.audit.filter(a=>!workspace||inYear(a.created_at.slice(0,10)));return result;}
 if(action==='session')return demoSession();
 if(action==='select_workspace'){
  persist();if(d.company_key!==demoCompany)demoUser=null;demoCompany=d.company_key;demoYear=Number(d.financial_year);
  try{state=JSON.parse(localStorage.getItem(demoStorageKey()))||demoSeed(demoCompany)}catch{state=demoSeed(demoCompany)}
  demoRecords=state;return demoSession();
 }
 if(action==='logout'){demoUser=null;return {ok:true};}
 if(action==='login'){demoUser={id:1,name:'DEMO ADMIN',role:'admin'};return demoSession();}
state=demoRecords||state;const id=()=>Date.now();let result={ok:true};const n=id();
if(action==='master'){if(state.masters.some(x=>x.kind===d.kind&&x.name.toLowerCase()===d.name.trim().toLowerCase()))throw Error('This master already exists.');state.masters.push({...d,name:d.kind==='vehicle'?d.name.toUpperCase().replace(/\s/g,''):d.name,id:n});result.id=n}
if(action==='purchase'){if(state.purchases.some(x=>+x.vehicle_id===+d.vehicle_id))throw Error('This vehicle already has a purchase.');state.purchases.unshift({...d,id:n})}
if(action==='sale'){const p=state.purchases.find(x=>+x.vehicle_id===+d.vehicle_id);if(!p)throw Error('Purchase this vehicle first.');if(state.sales.some(x=>+x.vehicle_id===+d.vehicle_id))throw Error('This vehicle is already sold.');if(d.sale_date<p.purchase_date)throw Error('Sale date cannot precede purchase date.');state.sales.unshift({...d,id:n})}
if(action==='expense'){
 if(Array.isArray(d.bills)){
  const purchase=state.purchases.find(x=>+x.vehicle_id===+d.vehicle_id);
  if(!purchase)throw Error('Select a purchased vehicle.');
  validateExpenseBillRows(d.bills,purchase.purchase_date);
  const existing=new Set(state.expenses.map(x=>x.bill_no.trim().toUpperCase()));
  for(const bill of d.bills)if(existing.has(bill.bill_no.trim().toUpperCase()))throw Error('Bill number '+bill.bill_no+' already exists.');
  d.bills.forEach((bill,index)=>{const rowId=n+index;state.expenses.unshift({id:rowId,vehicle_id:d.vehicle_id,party_id:d.party_id,bill_no:bill.bill_no.trim().toUpperCase(),expense_date:bill.bill_date});state.expense_items.push({id:rowId,expense_id:rowId,name:bill.name.trim().toUpperCase(),qty:1,total:bill.total})});
 }else{
  if(state.expenses.some(x=>x.bill_no.toLowerCase()===d.bill_no.trim().toLowerCase()))throw Error('Bill number must be unique.');
  const p=state.purchases.find(x=>+x.vehicle_id===+d.vehicle_id);if(!p||d.expense_date<p.purchase_date)throw Error('Expense date must be on or after purchase date.');
  state.expenses.unshift({...d,id:n,items:undefined});d.items.forEach((x,i)=>state.expense_items.push({...x,id:n+i,expense_id:n}));
 }
}
if(action==='user'){if(state.users.some(x=>x.username.toLowerCase()===d.username.toLowerCase()))throw Error('Username already exists.');state.users.push({id:n,name:d.name,username:d.username,role:d.role,active:1})}
if(action==='toggle_user'){if(+d.id===+user.id)throw Error('You cannot disable your own account.');const u=state.users.find(x=>+x.id===+d.id);u.active=u.active?0:1}
if(action==='document'){const file=d.get('file');if(!file||file.size>10*1024*1024||!['application/pdf','image/jpeg','image/png'].includes(file.type))throw Error('Upload a PDF, JPEG or PNG, maximum 10 MB.');state.documents.unshift({id:n,vehicle_id:d.get('vehicle_id'),document_id:d.get('document_id'),expiry_date:d.get('expiry_date'),original_name:file.name,demo:true});}
state.audit.unshift({id:n,user_name:user.name,action:({master:'Created '+d.kind,purchase:'Recorded purchase',sale:'Recorded sale',expense:'Recorded expense',user:'Created user',document:'Added document metadata',toggle_user:'Changed user status'})[action],created_at:new Date().toISOString().slice(0,19).replace('T',' ')});persist();return result}
async function refresh(){state=await request('state');if(state.workspace)workspace=state.workspace;for(const table of ['masters','purchases','sales','expenses','expense_items','users'])state[table]=(state[table]||[]).map(record=>normalizeEntry('master',record))}
function navigate(p){page=p;search='';filter='all';render();window.scrollTo(0,0)}
function shell(body){const stock=ledger().filter(x=>!x.sale).length;return `<div class="shell"><aside class="sidebar">${brand()}<button type="button" class="workspace-switch" data-workspace><strong>${esc(workspace?.company_name||'THE CAR PROJECT')}</strong><span>FY ${esc(workspace?.financial_year.label||'All years')} · Change ${icon('chevron')}</span></button><div class="sidebar-scroll"><nav aria-label="Main navigation"><div class="navlabel">WORKSPACE</div>${nav.map(([p,i,label],idx)=>(p==='users'&&user.role!=='admin'?'':`${idx===7?'<div class="navlabel">MANAGEMENT</div>':''}<button class="navitem ${page===p?'active':''}" data-nav="${p}">${icon(i)}${label}${p==='vehicles'?`<span class="badge">${stock}</span>`:''}</button>`)).join('')}</nav><div class="helpbox">${icon('shield')}<b>Your business. In perspective.</b>Every vehicle, every rupee, one clear picture.</div></div><div class="sidebarfoot"><div class="profile"><span class="avatar">${esc(user.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><div>${esc(user.name)}<small>${esc(user.role)} account</small></div></div><button type="button" class="sidebarlogout" data-logout>${icon('logout')}<span>Log out</span></button></div></aside><main class="main"><header class="topbar"><button class="iconbtn mobilemenu" id="menu" aria-label="Open navigation">${icon('menu')}</button><span class="crumb">${esc(workspace?.company_name||'Workspace')} &nbsp; / &nbsp; <b>${esc(nav.find(x=>x[0]===page)?.[2])}</b></span><div class="topright"><span class="date">${new Date().toLocaleDateString('en-IN',{weekday:'short',day:'numeric',month:'short',year:'numeric'})}</span><span class="dotlabel"><i class="dot"></i>${DEMO?'Design preview':'Connected'}</span><button class="iconbtn" data-nav="documents" aria-label="Document checklist">${icon('bell')}</button><span class="avatar">${esc(user.name[0])}</span><button type="button" class="btn headerlogout" data-logout>${icon('logout')}Log out</button></div></header><div class="content">${DEMO?'<div class="previewnote"><span>INTERACTIVE PREVIEW · Sample data saved only in this browser. No live database.</span><button id="reset">Reset demo</button></div>':''}<div class="workspace-banner"><div><strong>${esc(workspace?.company_name||'THE CAR PROJECT')}</strong><span>Financial year ${esc(workspace?.financial_year.label||'All years')} · April–March</span></div><button type="button" class="btn" data-workspace>Change company / year</button></div>${body}<p class="disclaimer">THE CAR PROJECT &nbsp;·&nbsp; Dealership workspace ${DEMO?'· Sample figures for demonstration':''}</p></div></main><nav class="mobilebottom" aria-label="Mobile navigation">${[['dashboard','grid','Home'],['vehicles','car','Vehicles'],['purchases','buy','Purchase'],['expenses','receipt','Expenses'],['masters','layers','Masters']].map(([p,i,l])=>`<button data-nav="${p}" class="${page===p?'active':''}">${icon(i)}${l}</button>`).join('')}</nav></div>`}
function head(title,subtitle,action='',label=''){return `<div class="pagehead"><div><div class="eyebrow">YOUR DEALERSHIP, CONNECTED</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="actions">${page==='dashboard'?`<button class="btn" data-export="vehicles">${icon('download')}Export</button>`:''}${action&&can(action)?`<button class="btn primary" data-form="${action}">${icon('plus')}${label}</button>`:''}</div></div>`}
function stat(label,value,foot,i,dark=false){return `<div class="stat ${dark?'dark':''}"><div class="statlabel">${label}${icon(i)}</div><div class="statvalue">${value}</div><div class="statfoot">${foot}</div></div>`}
function dashboard(){const l=viewLedger(),sold=l.filter(x=>x.sale&&inYear(x.sale.sale_date)),stock=l.filter(x=>!x.sale),profit=sold.reduce((a,x)=>a+x.profit,0),rev=sold.reduce((a,x)=>a+Number(x.sale.amount),0),invest=stock.reduce((a,x)=>a+x.cost,0);return head('Your business at a glance','A clear view of your inventory, sales and profitability.','purchase','New purchase')+`<div class="stats">${stat('Realized net profit',compact(profit),`<b>${sold.length} vehicles sold</b> · after all recorded costs`,'chart',true)}${stat('Vehicles in stock',String(stock.length).padStart(2,'0'),`${yearPurchases().length} purchased this FY · ${sold.length} sold`,'car')}${stat('Inventory investment',compact(invest),'Purchase + yard + recorded expenses','wallet')}${stat('Total sales revenue',compact(rev),`${sold.length} completed sales`,'rupee')}</div><div class="dashboardgrid"><section class="card"><div class="cardhead"><h2>Purchase & sales overview</h2><div class="tabs"><button data-chart="6m" class="${chartMode==='6m'?'active':''}">6 months</button><button data-chart="12m" class="${chartMode==='12m'?'active':''}">12 months</button></div></div>${chart()}</section><section class="card"><div class="cardhead"><h2>Keep things moving</h2><small>Quick actions</small></div><div class="quickgrid">${[['purchase','buy','Add purchase','Bring a vehicle in'],['sale','sell','Record sale','Close your next deal'],['expense','receipt','Add expense','Keep every cost'],['document','folder','Upload document','Complete the file']].filter(x=>can(x[0])).map(([f,i,t,s])=>`<button class="quick" data-form="${f}"><span>${icon(i)}</span><div>${t}<small>${s}</small></div></button>`).join('')}</div><div class="notice">${icon('alert')}<div><b>${missingCount()} vehicles need document review</b>Check RC, insurance and other required papers.<a href="#documents" data-nav="documents">Review documents →</a></div></div></section></div><section class="card"><div class="cardhead"><div><h2>Vehicle workspace</h2><small>Your latest purchases and completed sales</small></div><button class="textlink" data-nav="vehicles">View all vehicles →</button></div>${vehicleTable(l.slice(0,5))}</section><div class="bottomgrid"><section class="card"><div class="cardhead"><h2>Recent activity</h2><button class="textlink" data-nav="activity">View log →</button></div>${activities(3)}</section><section class="card"><div class="cardhead"><h2>Inventory health</h2>${icon('car')}</div><div class="overview"><div class="overviewrow"><span>Vehicles purchased</span><b>${l.length}</b></div><div class="progress"><span style="width:${l.length?stock.length/l.length*100:0}%"></span><span style="width:${l.length?sold.length/l.length*100:0}%"></span></div><div class="overviewrow"><span>● In stock &nbsp; ${stock.length}</span><span>● Sold &nbsp; ${sold.length}</span></div><div class="overviewrow"><span>Recorded vehicle expenses</span><b>${rupees(state.expense_items.reduce((a,x)=>a+Number(x.total),0))}</b></div><div class="overviewrow"><span>Average profit per sale</span><b class="profit">${rupees(sold.length?profit/sold.length:0)}</b></div></div></section></div>`}
function chart(){const count=chartMode==='6m'?6:12,months=[];for(let i=count-1;i>=0;i--){const d=workspace?new Date(workspace.financial_year.end+'T12:00:00'):new Date();d.setDate(1);d.setMonth(d.getMonth()-i);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;months.push({label:d.toLocaleDateString('en',{month:'short'}),purchase:yearPurchases().filter(x=>x.purchase_date.startsWith(key)).reduce((a,x)=>a+Number(x.amount),0),sale:yearSales().filter(x=>x.sale_date.startsWith(key)).reduce((a,x)=>a+Number(x.amount),0)})}const max=Math.max(...months.map(x=>Math.max(x.purchase,x.sale)),1);return `<div class="chartwrap"><div class="charttop"><div><strong>${compact(months.reduce((a,x)=>a+x.sale,0))}</strong> <small class="subtitle">sales in period</small></div><div class="legend"><span><i></i>Purchases</span><span><i class="gold"></i>Sales</span></div></div><div class="barchart" role="img" aria-label="Monthly purchase and sale amounts">${months.map(x=>`<div class="barcol" title="${x.label}: Purchase ${rupees(x.purchase)}, Sale ${rupees(x.sale)}"><i style="height:${x.purchase/max*90}%"></i><i class="gold" style="height:${x.sale/max*90}%"></i><small>${x.label}</small></div>`).join('')}</div><div class="chartfoot">Gross transaction amounts · Hover a month for details</div></div>`}
function missingCount(){return ledger().filter(p=>['RC','Insurance'].some(name=>!state.documents.some(d=>+d.vehicle_id===+p.vehicle_id&&m(d.document_id).name===name))).length}
function vehicleTable(rows){return rows.length?`<div class="tablewrap"><table><thead><tr><th>Vehicle</th><th>Purchased</th><th>Total cost</th><th>Sale amount</th><th>Net profit</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><div class="vehiclecell"><span class="carthumb">${icon('car')}</span><div><strong>${esc(r.vehicle.name)}</strong><small>${esc(r.vehicle.details||'Vehicle record')}</small></div></div></td><td>${esc(r.purchase_date)}</td><td>${rupees(r.cost)}</td><td>${r.sale?rupees(r.sale.amount):'—'}</td><td class="${r.profit<0?'negative':'profit'}">${r.profit===null?'—':rupees(r.profit)}</td><td><span class="pill ${r.sale?'':'amber'}">${r.status}</span></td><td><button class="textlink" data-detail="${r.vehicle_id}" aria-label="Open ${esc(r.vehicle.name)}">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div><div class="tablefoot"><span>${rows.length} vehicle${rows.length===1?'':'s'}</span><span>All amounts in INR</span></div>`:empty('No vehicles found. Add your first purchase to begin.')}
function empty(text){return `<div class="empty">${icon('folder')}${text}</div>`}
function vehicles(){let rows=viewLedger().filter(x=>(filter==='all'||(filter==='sold'?x.sale:!x.sale))&&(`${x.vehicle.name} ${x.vehicle.details}`).toLowerCase().includes(search.toLowerCase()));return head('Vehicle inventory','Every car, from purchase to a profitable sale.','purchase','New purchase')+`<section class="card"><div class="tabletools"><div class="search">${icon('search')}<input id="search" aria-label="Search vehicles" placeholder="Search vehicle or model…" value="${esc(search)}"></div><div class="tabs">${[['all','All vehicles'],['stock','In stock'],['sold','Sold']].map(([v,l])=>`<button data-filter="${v}" class="${filter===v?'active':''}">${l}</button>`).join('')}</div></div>${vehicleTable(rows)}</section>`}
function table(headers,rows){return rows.length?`<div class="tablewrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty('No records yet. Use the add button to get started.')}
function listings(){let title,sub,action,label,headers,rows;
if(page==='purchases'){title='Purchases';sub='Vehicle acquisition, bank, yard and portal details.';action='purchase';label='New purchase';headers=['Vehicle','Purchase date','Seller','Bank / portal','Purchase amount','Yard expense','Manager'];rows=yearPurchases().map(p=>[`<strong>${esc(m(p.vehicle_id).name)}</strong>`,esc(p.purchase_date),esc(m(p.client_id).name),esc(m(p.bank_id).name)+'<small>'+esc(m(p.portal_id).name)+'</small>',rupees(p.amount),rupees(p.yard_expense),esc(p.manager_name)+'<small>'+esc(p.manager_contact)+'</small>'])}
if(page==='sales'){title='Sales';sub='Completed deals with clear costs and realized profit.';action='sale';label='Record sale';headers=['Vehicle','Buyer','Sale date','Sale amount','Sale expense','Net sales','Net profit'];rows=ledger().filter(x=>x.sale&&inYear(x.sale.sale_date)).map(p=>[`<strong>${esc(p.vehicle.name)}</strong>`,esc(m(p.sale.client_id).name),esc(p.sale.sale_date),rupees(p.sale.amount),rupees(p.sale.sale_expense),rupees(p.sale.amount-p.sale.sale_expense),`<span class="${p.profit<0?'negative':'profit'}">${rupees(p.profit)}</span>`])}
if(page==='expenses'){title='Vehicle expenses';sub='Every bill and every item, linked to the right vehicle.';action='expense';label='Add expense';headers=['Bill number','Vehicle','Party','Date','Items','Bill total',''];rows=yearExpenses().map(e=>{const items=state.expense_items.filter(i=>+i.expense_id===+e.id);return [`<strong>${esc(e.bill_no)}</strong>`,esc(m(e.vehicle_id).name),esc(m(e.party_id).name),esc(e.expense_date),items.length,rupees(items.reduce((a,x)=>a+Number(x.total),0)),`<button class="textlink" data-bill="${e.id}">View bill →</button>`]})}
return head(title,sub,action,label)+`<section class="card"><div class="cardhead"><h2>All ${title.toLowerCase()}</h2><button class="btn" data-export="${page}">${icon('download')}Export CSV</button></div>${table(headers,rows)}</section>`}
function masterPage(){const rows=all(masterKind).filter(x=>`${x.name} ${x.details||''} ${x.city||''}`.toLowerCase().includes(search.toLowerCase()));return head('Master records','Your reusable directory. Also available to add inside every entry form.')+`<div class="mastertabs">${Object.entries(kinds).map(([k,l])=>`<button data-kind="${k}" class="${k===masterKind?'active':''}">${l} <small>${all(k).length}</small></button>`).join('')}</div><section class="card"><div class="tabletools"><div class="search">${icon('search')}<input id="search" aria-label="Search master records" placeholder="Search ${esc(kinds[masterKind].toLowerCase())}…" value="${esc(search)}"></div>${can('master')?`<button class="btn primary" data-add-master="${masterKind}">${icon('plus')}Add ${esc(kindSingular[masterKind])}</button>`:''}</div>${table(['Name / number','Contact','Address / city','Details'],rows.map(x=>[`<strong>${esc(x.name)}</strong>`,esc(x.contact||'—'),esc([x.address,x.city].filter(Boolean).join(', ')||'—'),esc(x.details||'—')]))}</section>`}
function documentsPage(){return head('Document centre','Upload vehicle papers and track what still needs attention.','document','Upload document')+`<section class="card"><div class="cardhead"><h2>Vehicle document checklist</h2><small>${missingCount()} need RC / insurance review</small></div>${table(['Vehicle',...all('document').map(x=>esc(x.name))],ledger().map(v=>[`<button class="textlink" data-detail="${v.vehicle_id}">${esc(v.vehicle.name)}</button>`,...all('document').map(t=>{const docs=state.documents.filter(d=>+d.vehicle_id===+v.vehicle_id&&+d.document_id===+t.id);const d=docs[0];return d?`<button class="textlink" data-download="${d.id}"><span class="pill ${d.expiry_date&&d.expiry_date<today()?'red':''}">${d.expiry_date&&d.expiry_date<today()?'Expired':'Uploaded'}</span></button>`:'<span class="pill amber">Pending</span>'})]))}</section><section class="card" style="margin-top:22px"><div class="cardhead"><h2>Uploaded documents</h2><small>PDF, JPG, PNG · up to 10 MB</small></div>${table(['Vehicle','Document type','File','Expiry',''],state.documents.map(d=>[esc(m(d.vehicle_id).name),esc(m(d.document_id).name),esc(d.original_name),esc(d.expiry_date||'—'),`<button class="textlink" data-download="${d.id}">Download ↓</button>`]))}</section>`}
function reports(){const l=viewLedger(),sold=l.filter(x=>x.sale&&inYear(x.sale.sale_date)),profit=sold.reduce((a,x)=>a+x.profit,0),cost=sold.reduce((a,x)=>a+x.cost+(+x.sale.sale_expense),0);return head('Profit & performance','Profit is calculated from completed sales and all recorded vehicle costs.')+`<div class="stats">${stat('Realized net profit',compact(profit),'After purchase, yard, bills & sale costs','chart',true)}${stat('Completed sales',sold.length,'Vehicles with a recorded sale','sell')}${stat('Total sold vehicle costs',compact(cost),'Includes sale expenses','receipt')}${stat('Unsold investment',compact(l.filter(x=>!x.sale).reduce((a,x)=>a+x.cost,0)),'Held in current inventory','wallet')}</div><section class="card"><div class="cardhead"><h2>Vehicle profit ledger</h2><button class="btn" data-export="reports">${icon('download')}Export CSV</button></div>${table(['Vehicle','Purchase','Yard','Post-purchase costs','Sale costs','Sale price','Net sales','Profit / loss'],sold.map(x=>[`<strong>${esc(x.vehicle.name)}</strong>`,rupees(x.amount),rupees(x.yard_expense),rupees(x.expenses),rupees(x.sale.sale_expense),rupees(x.sale.amount),rupees(x.sale.amount-x.sale.sale_expense),`<span class="${x.profit<0?'negative':'profit'}">${rupees(x.profit)}</span>`]))}<div class="tablefoot">Profit = sale amount − purchase − yard expenses − bill item totals − sale expenses. Shared overheads and tax are not included unless recorded as vehicle expenses.</div></section>`}
function usersPage(){return head('Users & access','Control who can manage purchases, expenses and business records.','user','Add user')+`<section class="card">${table(['Name','Username','User type','Status',''],state.users.map(u=>[`<strong>${esc(u.name)}</strong>`,esc(u.username),`<span class="roletag">${esc(u.role)}</span>`,`<span class="pill ${+u.active?'':'red'}">${+u.active?'Active':'Disabled'}</span>`,+u.id===+user.id?'Your account':`<button class="textlink" data-toggle-user="${u.id}">${+u.active?'Disable':'Enable'}</button>`]))}</section><section class="card" style="margin-top:22px"><div class="cardhead"><h2>Permissions by user type</h2></div>${table(['User type','Permissions'],[['Admin','All records, masters, transactions and user management'],['Manager','View records; add purchases, sales, expenses, masters and documents'],['Accountant','View records; add expenses, masters and documents'],['Viewer','View records, reports and download documents']])}</section>`}
function activities(limit=100){return `<div class="activity">${state.audit.slice(0,limit).map(a=>`<div class="activityrow"><span class="activityicon">${icon(a.action?.includes('sale')?'sell':a.action?.includes('purchase')?'buy':'clock')}</span><div><strong>${esc(a.action)}</strong><small>${esc(a.user_name)}</small></div><time>${esc(a.created_at?.slice(0,16))}</time></div>`).join('')||empty('Activity will appear as your team works.')}</div>`}
function render(){let body=page==='dashboard'?dashboard():page==='vehicles'?vehicles():['purchases','sales','expenses'].includes(page)?listings():page==='masters'?masterPage():page==='documents'?documentsPage():page==='reports'?reports():page==='users'?usersPage():head('Activity log','A record of who added transactions and changed access.')+`<section class="card">${activities()}</section>`;$('#root').innerHTML=shell(body);bindShell()}
function bindShell(){ $$('[data-workspace]').forEach(b=>b.onclick=openWorkspace); $$('[data-nav]').forEach(el=>el.onclick=e=>{e.preventDefault();navigate(el.dataset.nav)});$$('[data-form]').forEach(el=>el.onclick=()=>openForm(el.dataset.form));$$('[data-detail]').forEach(el=>el.onclick=()=>detail(el.dataset.detail));$$('[data-bill]').forEach(el=>el.onclick=()=>billDetail(el.dataset.bill));$$('[data-filter]').forEach(el=>el.onclick=()=>{filter=el.dataset.filter;render()});$$('[data-chart]').forEach(el=>el.onclick=()=>{chartMode=el.dataset.chart;render()});$$('[data-kind]').forEach(el=>el.onclick=()=>{masterKind=el.dataset.kind;search='';render()});$$('[data-add-master]').forEach(el=>el.onclick=()=>addMaster(el.dataset.addMaster));$$('[data-export]').forEach(el=>el.onclick=()=>exportCSV(el.dataset.export));$$('[data-download]').forEach(el=>el.onclick=()=>download(el.dataset.download));$$('[data-toggle-user]').forEach(el=>el.onclick=async()=>{try{await request('toggle_user',{id:el.dataset.toggleUser});await refresh();render();toast('User status updated')}catch(e){toast(e.message)}});if($('#menu'))$('#menu').onclick=()=>$('.sidebar').classList.toggle('open');if($('#search'))$('#search').oninput=e=>{const pos=e.target.selectionStart;search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)};if($('#reset'))$('#reset').onclick=()=>{if(confirm('Reset all sample records in this browser?')){state=demoSeed(demoCompany);demoRecords=state;persist();render();toast('Demo reset')}};$$('[data-logout]').forEach(button=>button.onclick=async()=>{const buttons=$$('[data-logout]');buttons.forEach(b=>b.disabled=true);try{await request('logout',{});user=null;const session=await request('session');applySession(session);loginView()}catch(err){toast(err.message)}finally{buttons.forEach(b=>b.disabled=false)}})}
function modal(title,subtitle,html,wide=false){const layer=document.createElement('div');layer.className='modalback';layer.innerHTML=`<section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modalhead"><div><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div><button type="button" class="close" aria-label="Close dialog">×</button></div>${html}</section>`;const previous=document.activeElement;$('#layers').append(layer);document.body.style.overflow='hidden';const close=()=>{layer.remove();if(!$('#layers').children.length)document.body.style.overflow='';previous?.focus()};$('.close',layer).onclick=close;layer.addEventListener('keydown',e=>{if(e.key==='Escape'){e.stopPropagation();close()}if(e.key==='Tab'){const list=$$('button,input,select,textarea,a[href]',layer).filter(x=>!x.disabled),first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});setTimeout(()=>$('input,select,button',layer)?.focus(),0);return {layer,close}}
function field(label,name,type='text',required=true,value=''){return `<div class="field"><label for="${name}">${label}${required?' *':''}</label><input id="${name}" name="${name}" type="${type}" ${required?'required':''} ${type==='number'?'min="0" max="9999999999.99" step="0.01"':''} value="${esc(value)}" ${type==='password'?'minlength="12" maxlength="128" autocomplete="new-password"':'maxlength="160"'}></div>`}
function selectField(label,name,kind,required=true,eligible=null){const opts=eligible||all(kind);return `<div class="field"><label for="${name}">${label}${required?' *':''}</label><input class="selectsearch" type="search" data-search-select="${name}" placeholder="Type to filter options…" aria-label="Search options for ${label}"><div class="selectrow"><select id="${name}" name="${name}" ${required?'required':''} data-master-select="${kind}"><option value="">Select ${esc(kindSingular[kind])}…</option>${opts.map(x=>`<option value="${x.id}">${esc(x.name+(x.details&&kind==='vehicle'?' · '+x.details:''))}</option>`).join('')}</select>${can('master')?`<button type="button" class="addmini" data-quick="${kind}" data-target="${name}" aria-label="Add ${esc(kindSingular[kind])}">+</button>`:''}</div>${kind==='vehicle'?'<small>Select by registration number</small>':''}</div>`}
function addMaster(kind,target=null){if(!can('master'))return;const {layer,close}=modal('Add '+kindSingular[kind],target?'Save & select without leaving your entry.':'Create a reusable master record.',`<form id="master-form"><div class="formgrid">${field(kind==='vehicle'?'Vehicle registration number':'Name','name')}${kind==='document'||kind==='portal'?'':field('Contact number','contact','tel',false)}${kind==='vehicle'?field('Make, model, year & fuel','details','text',false):kind==='document'||kind==='portal'?field('Notes','details','text',false):field('Details / branch','details','text',false)}${!['vehicle','document','portal'].includes(kind)?field('City','city','text',false)+field('Address','address','text',false):''}</div><div class="error" role="alert"></div><div class="formfooter"><small>Duplicate names are checked.</small><button class="btn primary" type="submit">${icon('check')}${target?'Save & select':'Save master'}</button></div></form>`);const form=$('form',layer);form.onsubmit=async e=>{e.preventDefault();const btn=$('[type=submit]',form);btn.disabled=true;try{const d=Object.fromEntries(new FormData(form));d.kind=kind;await request('master',d);await refresh();const created=all(kind).find(x=>x.name.toUpperCase()===(kind==='vehicle'?d.name.replace(/\s/g,''):d.name).trim().toUpperCase());if(target){const selects=$$(`select[data-master-select="${kind}"]`);selects.forEach(s=>{if(![...s.options].some(o=>+o.value===+created.id))s.add(new Option(created.name,created.id));if(s===target){s.value=created.id;s.dispatchEvent(new Event('change',{bubbles:true}))}})}else render();close();toast('Master saved'+(target?' and selected':''))}catch(err){$('.error',form).textContent=err.message}finally{btn.disabled=false}}}
function openForm(type){if(!can(type))return;const purchased=all('vehicle').filter(v=>state.purchases.some(p=>+p.vehicle_id===+v.id)),stock=purchased.filter(v=>!state.sales.some(s=>+s.vehicle_id===+v.id));let fields='',summary='',title='',description='';
if(type==='purchase'){title='New vehicle purchase';description='Record the acquisition and all initial costs.';fields=selectField('Vehicle number','vehicle_id','vehicle',true,all('vehicle').filter(v=>!state.purchases.some(p=>+p.vehicle_id===+v.id)))+field('Purchase date','purchase_date','date',true,entryToday())+selectField('Bank','bank_id','bank',false)+selectField('Seller','client_id','client',false)+field('Purchase amount (₹)','amount','number')+field('Yard expenses (₹)','yard_expense','number',true,'0')+selectField('Yard','yard_id','yard',false)+selectField('Purchase portal','portal_id','portal',false)+field('Manager name','manager_name','text',false)+field('Manager contact','manager_contact','tel',false);summary='<div class="summarybox" id="form-summary"></div>'}
if(type==='sale'){title='Record a sale';description='Select an in-stock vehicle and record the deal.';fields=selectField('Vehicle number','vehicle_id','vehicle',true,stock)+selectField('Buyer / customer','client_id','client')+field('Sale date','sale_date','date',true,entryToday())+field('Salesperson name','salesperson','text',false)+field('Sale amount (₹)','amount','number')+field('Sale expenses (₹)','sale_expense','number',true,'0');summary='<div class="summarybox" id="form-summary"></div>'}
if(type==='expense'){title='Add vehicle expense';description='Add a separate bill number, date, item and amount on each row.';fields=selectField('Vehicle number','vehicle_id','vehicle',true,purchased)+selectField('Party / vendor','party_id','party');summary=`<div class="items expense-bills"><div class="expense-bill-header"><span>BILL NO. *</span><span>DATE OF BILL *</span><span>ITEM NAME *</span><span>BILL AMOUNT ₹ *</span><span></span></div><div id="bill-rows"></div><button class="btn" type="button" id="add-bill-row">${icon('plus')}Add bill row</button></div><div class="summarybox" id="form-summary"></div>`}
if(type==='document'){title='Upload vehicle document';description=DEMO?'Preview saves file metadata only. Files are not uploaded.':'Files are stored privately and downloaded after login.';fields=selectField('Vehicle number','vehicle_id','vehicle')+selectField('Document type','document_id','document')+field('Expiry date (optional)','expiry_date','date',false)+`<div class="field"><label for="file">Document file *</label><input id="file" name="file" type="file" accept="application/pdf,image/jpeg,image/png" required><small>PDF, JPEG or PNG · maximum 10 MB</small></div>`}
if(type==='user'){title='Add team member';description='Provide a unique username and assign permissions.';fields=field('Full name','name')+field('Username','username')+field('Password (12+ characters)','password','password')+`<div class="field"><label for="role">User type *</label><select id="role" name="role" required><option value="manager">Manager</option><option value="accountant">Accountant</option><option value="viewer">Viewer</option><option value="admin">Admin</option></select></div>`}
const {layer,close}=modal(title,description,`<form id="entry-form"><div class="sectiontitle"><span>01</span>${type==='expense'?'Bill details':type==='user'?'Account details':type==='document'?'Document details':'Vehicle & transaction details'}</div><div class="formgrid">${fields}</div>${summary}<div class="error" role="alert"></div><div class="formfooter"><small>* Required fields<br>Amounts are in INR</small><button class="btn primary" type="submit">${icon('check')}${type==='document'?'Save document':type==='user'?'Create user':'Save '+type}</button></div></form>`,true);const form=$('form',layer);$$('[data-search-select]',form).forEach(input=>{const sel=form.elements[input.dataset.searchSelect];input.oninput=()=>{const current=sel.value,kind=sel.dataset.masterSelect;let options=all(kind);if(kind==='vehicle'&&type==='purchase')options=options.filter(v=>!state.purchases.some(p=>+p.vehicle_id===+v.id));if(kind==='vehicle'&&type==='sale')options=options.filter(v=>state.purchases.some(p=>+p.vehicle_id===+v.id)&&!state.sales.some(p=>+p.vehicle_id===+v.id));if(kind==='vehicle'&&type==='expense')options=options.filter(v=>state.purchases.some(p=>+p.vehicle_id===+v.id));const term=input.value.toLowerCase();sel.innerHTML='<option value="">Select an option…</option>'+options.filter(v=>+v.id===+current||(v.name+' '+(v.details||'')).toLowerCase().includes(term)).map(v=>`<option value="${v.id}">${esc(v.name+(kind==='vehicle'&&v.details?' · '+v.details:''))}</option>`).join('');sel.value=current}});$$('[data-quick]',form).forEach(b=>b.onclick=()=>addMaster(b.dataset.quick,form.elements[b.dataset.target]));if(type==='expense'){$('#add-bill-row',form).onclick=()=>addExpenseBillRow(form);addExpenseBillRow(form)}
form.addEventListener('input',()=>updateSummary(type,form));form.addEventListener('change',()=>updateSummary(type,form));updateSummary(type,form);
form.onsubmit=async e=>{e.preventDefault();const btn=$('[type=submit]',form);btn.disabled=true;try{let data=new FormData(form);if(type!=='document'){data=Object.fromEntries(data);if(type==='expense'){data.bills=$$('[data-bill-row]',form).map(row=>({bill_no:$('[data-bill-no]',row).value,bill_date:$('[data-bill-date]',row).value,name:$('[data-name]',row).value,total:$('[data-total]',row).value}));validateExpenseBillRows(data.bills,state.purchases.find(p=>+p.vehicle_id===+data.vehicle_id)?.purchase_date)}}await request(type,data);await refresh();close();render();toast(type==='document'&&DEMO?'Document metadata saved for preview':'Record saved successfully')}catch(err){$('.error',form).textContent=err.message}finally{btn.disabled=false}}}
function validateExpenseBillRows(bills,purchaseDate){
 if(!Array.isArray(bills)||bills.length<1||bills.length>100)throw Error('Add between 1 and 100 bill rows.');
 const seen=new Set();
 for(const [index,bill] of bills.entries()){
  const no=String(bill.bill_no??'').trim().toUpperCase(),date=String(bill.bill_date??'');
  if(!no||no.length>100)throw Error('Enter a bill number of up to 100 characters on row '+(index+1)+'.');
  if(seen.has(no))throw Error('Bill number '+no+' is repeated. Every row needs a unique bill number.');seen.add(no);
  const parsedDate=new Date(date+'T00:00:00Z');
  if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(parsedDate.getTime())||parsedDate.toISOString().slice(0,10)!==date)throw Error('Enter a valid bill date on row '+(index+1)+'.');
  if(purchaseDate&&date<purchaseDate)throw Error('Bill date on row '+(index+1)+' cannot precede the purchase date.');
  if(!String(bill.name??'').trim()||String(bill.name).trim().length>200)throw Error('Enter an item name of up to 200 characters on row '+(index+1)+'.');
  if(!/^\d{1,10}(\.\d{1,2})?$/.test(String(bill.total??'')))throw Error('Enter a valid bill amount on row '+(index+1)+'.');
 }
}
function addExpenseBillRow(form){
 if($$('[data-bill-row]',form).length>=100)return toast('You can add up to 100 bill rows.');
 const row=document.createElement('div');row.className='expense-bill-row';row.dataset.billRow='true';
 row.innerHTML=`<label class="bill-cell"><span>Bill no. *</span><input data-bill-no required maxlength="100" placeholder="BILL-001" aria-label="Bill no."></label><label class="bill-cell"><span>Date of bill *</span><input data-bill-date type="date" value="${entryToday()}" required aria-label="Date of bill"></label><label class="bill-cell"><span>Item name *</span><input data-name required maxlength="200" placeholder="ENGINE SERVICE" aria-label="Item name"></label><label class="bill-cell"><span>Bill amount ₹ *</span><input data-total type="number" min="0" max="9999999999.99" step="0.01" placeholder="0.00" required aria-label="Bill amount"></label><button type="button" class="remove-bill-row" aria-label="Remove bill row">×</button>`;
 $('#bill-rows',form).append(row);$('button',row).onclick=()=>{if($$('[data-bill-row]',form).length===1)return toast('Keep at least one bill row.');row.remove();updateSummary('expense',form)};
 updateSummary('expense',form);
}
function updateSummary(type,form){const target=$('#form-summary',form);if(!target)return;const val=n=>Number(form.elements[n]?.value)||0;if(type==='purchase')target.innerHTML=`<div class="summaryrow"><span>Purchase amount</span><b>${rupees(val('amount'))}</b></div><div class="summaryrow"><span>Yard expenses</span><b>${rupees(val('yard_expense'))}</b></div><div class="summaryrow total"><span>Initial vehicle cost</span><b>${rupees(val('amount')+val('yard_expense'))}</b></div>`;
if(type==='sale'){const p=ledger().find(x=>+x.vehicle_id===val('vehicle_id')),net=val('amount')-val('sale_expense'),profit=net-(p?.cost||0);target.innerHTML=`<div class="summaryrow"><span>Total vehicle cost</span><b>${p?rupees(p.cost):'Select a purchased vehicle'}</b></div><div class="summaryrow"><span>Net sales (sale less sale expenses)</span><b>${rupees(net)}</b></div><div class="summaryrow total"><span>Projected net profit</span><b class="${profit<0?'negative':'profit'}">${p?rupees(profit):'—'}</b></div>`}
if(type==='expense'){const total=$$('[data-total]',form).reduce((a,x)=>a+(Number(x.value)||0),0);target.innerHTML=`<div class="summaryrow total"><span>Total expense amount</span><b>${rupees(total)}</b></div><small class="subtitle">Each row saves a separate bill. Every bill number must be unique across all vehicles.</small>`}}
function detail(id){const r=ledger().find(x=>+x.vehicle_id===+id);if(!r)return;const docs=state.documents.filter(x=>+x.vehicle_id===+id);const {layer}=modal('Vehicle ledger','The complete financial picture for this vehicle.',`<div class="detailhero"><span class="carthumb">${icon('car')}</span><div><h2>${esc(r.vehicle.name)}</h2><p>${esc(r.vehicle.details)}</p><span class="pill ${r.sale?'':'amber'}">${r.status}</span></div></div><div class="formgrid"><div><small class="subtitle">PURCHASED ON</small><p>${esc(r.purchase_date)}</p></div><div><small class="subtitle">BANK / PORTAL</small><p>${esc(m(r.bank_id).name)} / ${esc(m(r.portal_id).name)}</p></div><div><small class="subtitle">YARD</small><p>${esc(m(r.yard_id).name)}<br>${esc(m(r.yard_id).address)} ${esc(m(r.yard_id).city)}</p></div><div><small class="subtitle">MANAGER</small><p>${esc(r.manager_name)}<br>${esc(r.manager_contact)}</p></div></div><div class="summarybox">${[['Purchase amount',r.amount],['Yard expenses',r.yard_expense],['Post-purchase bills',r.expenses],['Total vehicle cost',r.cost],...(r.sale?[['Sale amount',r.sale.amount],['Sale expenses',r.sale.sale_expense],['Net sales',r.sale.amount-r.sale.sale_expense],['Net profit',r.profit]]:[])].map(([l,v],i)=>`<div class="summaryrow ${l==='Net profit'?'total':''}"><span>${l}</span><b>${rupees(v)}</b></div>`).join('')}</div><div class="items"><h3>Expense bills</h3>${table(['Bill no.','Party','Total'],state.expenses.filter(x=>+x.vehicle_id===+id).map(x=>[esc(x.bill_no),esc(m(x.party_id).name),rupees(state.expense_items.filter(i=>+i.expense_id===+x.id).reduce((a,i)=>a+Number(i.total),0))]))}<h3>Documents</h3>${docs.map(d=>`<p><button class="textlink" data-download="${d.id}">${esc(m(d.document_id).name)} · ${esc(d.original_name)} ↓</button></p>`).join('')||'<p class="subtitle">No documents uploaded yet.</p>'}</div>`,true);$$('[data-download]',layer).forEach(b=>b.onclick=()=>download(b.dataset.download))}
function billDetail(id){const bill=state.expenses.find(x=>+x.id===+id);if(!bill)return;const items=state.expense_items.filter(x=>+x.expense_id===+id);modal('Bill '+bill.bill_no,m(bill.vehicle_id).name+' · '+m(bill.party_id).name+' · '+bill.expense_date,table(['Bill no.','Date of bill','Item name','Bill amount'],items.map(x=>[esc(bill.bill_no),esc(bill.expense_date),esc(x.name),rupees(x.total)]))+`<div class="summarybox"><div class="summaryrow total"><span>Total</span><b>${rupees(items.reduce((a,x)=>a+Number(x.total),0))}</b></div></div>`,true)}
function download(id){if(DEMO)return toast('Preview stores metadata only. Document downloads work in the PHP application.');window.location.href='api.php?action=download&id='+encodeURIComponent(id)+'&workspace_token='+encodeURIComponent(workspaceToken)}
function exportCSV(type){let rows;if(type==='expenses')rows=[['Bill','Vehicle','Party','Date','Total'],...yearExpenses().map(e=>[e.bill_no,m(e.vehicle_id).name,m(e.party_id).name,e.expense_date,state.expense_items.filter(i=>+i.expense_id===+e.id).reduce((a,x)=>a+Number(x.total),0)])];else if(type==='purchases')rows=[['Vehicle','Purchase date','Amount','Yard costs','Bank','Portal'],...yearPurchases().map(p=>[m(p.vehicle_id).name,p.purchase_date,p.amount,p.yard_expense,m(p.bank_id).name,m(p.portal_id).name])];else rows=[['Vehicle','Purchase','Yard costs','Post purchase costs','Total cost','Sale','Sale costs','Net sales','Net profit','Status'],...viewLedger().filter(x=>!['sales','reports'].includes(type)||(x.sale&&inYear(x.sale.sale_date))).map(x=>[x.vehicle.name,x.amount,x.yard_expense,x.expenses,x.cost,x.sale?.amount??'',x.sale?.sale_expense??'',x.sale?x.sale.amount-x.sale.sale_expense:'',x.profit??'',x.status])];const csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=(workspace?.company_key||'the-car-project')+'-'+(workspace?.financial_year.year||'all')+'-'+type+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('CSV exported')}
function loginView(){ $('#root').innerHTML=`<div class="login"><div class="loginbrand">${brand()}<div class="eyebrow">THE BUSINESS BEHIND EVERY DRIVE</div><h1>Know every car.<br>Count every rupee.</h1><p>Your purchases, sales, expenses and documents. One workspace built for your dealership.</p></div><div class="loginform"><form><div class="eyebrow">WELCOME TO YOUR WORKSPACE</div><h2>Sign in to The Car Project</h2><p>Select your company and financial year, then sign in.</p><div class="workspace-login">${workspaceFields()}</div>${DEMO?'':field('Username','username')+field('Password','password','password')}<div class="error" role="alert"></div><button class="btn primary" type="submit">${DEMO?'Enter demo workspace':'Sign in securely'}${icon('arrow')}</button><p>${DEMO?'Sample data only. No password is needed to open a demo company.':''}</p></form></div></div>`;const f=$('form');bindWorkspaceFields(f);if(f.elements.password){f.elements.password.autocomplete='current-password';f.elements.password.removeAttribute('minlength');}f.onsubmit=async e=>{e.preventDefault();const btn=$('[type=submit]',f);btn.disabled=true;try{const data=Object.fromEntries(new FormData(f));if(data.company_key!==workspace?.company_key||Number(data.financial_year)!==workspace?.financial_year.year){const selected=await request('select_workspace',{company_key:data.company_key,financial_year:Number(data.financial_year)});applySession(selected)}const result=await request('login',{username:data.username,password:data.password});applySession(result);await refresh();render()}catch(err){$('.error',f).textContent=err.message}finally{btn.disabled=false}}}
async function init(){ $('#root').innerHTML='<div class="loading">Opening your dealership workspace…</div>';try{if(DEMO){try{state=JSON.parse(localStorage.getItem(demoStorageKey()))||demoSeed(demoCompany)}catch{state=demoSeed(demoCompany)}demoRecords=state;}const s=await request('session');applySession(s);if(user){await refresh();render()}else loginView()}catch(e){$('#root').innerHTML=`<div class="loading"><h1>Setup required</h1><p>${esc(e.message)}</p><p>Follow README.md to configure PHP and MySQL.</p></div>`}}
init();
